import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[2]; BASE=ROOT/"problems"/"shortest-paths"
tasks=[
{"slug":"10-count-shortest-routes","title":"Count Shortest Routes","method":"countShortestRoutes","ret":"int","params":[("n","int"),("roads","int[][]")],"diff":"Medium","subtopic":"Dijkstra","desc":"An undirected connected graph has `n` vertices numbered 0 through `n-1`. Each road is `[u, v, time]` with positive travel time. Count the distinct shortest routes from vertex 0 to vertex `n-1`, modulo 1,000,000,007. Input: `n` and `roads`. Output: the route count.","cons":["2 <= n <= 200","n-1 <= roads.length <= 10000","roads[i] = [u,v,time], 0 <= u,v < n, time > 0","The graph is connected and has no parallel roads"],"time":"O((n+m) log n)","space":"O(n+m)","py":"        graph = [[] for _ in range(n)]\n        for u, v, w in roads: graph[u].append((v,w)); graph[v].append((u,w))\n        dist = [float('inf')] * n; ways = [0] * n; dist[0] = 0; ways[0] = 1\n        heap = [(0,0)]; mod = 1000000007\n        while heap:\n            d,u = heappop(heap)\n            if d != dist[u]: continue\n            for v,w in graph[u]:\n                nd = d + w\n                if nd < dist[v]: dist[v] = nd; ways[v] = ways[u]; heappush(heap,(nd,v))\n                elif nd == dist[v]: ways[v] = (ways[v] + ways[u]) % mod\n        return ways[n-1]","java":"        int mod = 1000000007; List<int[]>[] graph = new ArrayList[n]; for (int i=0;i<n;i++) graph[i]=new ArrayList<>();\n        for (int[] e:roads) { graph[e[0]].add(new int[]{e[1],e[2]}); graph[e[1]].add(new int[]{e[0],e[2]}); }\n        long[] dist = new long[n]; Arrays.fill(dist,Long.MAX_VALUE); int[] ways = new int[n]; dist[0]=0; ways[0]=1;\n        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a->a[0])); pq.offer(new long[]{0,0});\n        while(!pq.isEmpty()) { long[] cur=pq.poll(); long d=cur[0]; int u=(int)cur[1]; if(d!=dist[u]) continue; for(int[] e:graph[u]) { int v=e[0]; long nd=d+e[1]; if(nd<dist[v]) { dist[v]=nd; ways[v]=ways[u]; pq.offer(new long[]{nd,v}); } else if(nd==dist[v]) ways[v]=(int)(((long)ways[v]+ways[u])%mod); } }\n        return ways[n-1];","examples":[({"n":7,"roads":[[0,6,7],[0,1,2],[1,2,3],[1,3,3],[6,3,3],[3,5,1],[6,5,1],[2,5,1],[0,4,5],[4,6,2]]},4),({"n":2,"roads":[[0,1,5]]},1)],"tests":[{"n":2,"roads":[[0,1,1]]},{"n":3,"roads":[[0,1,1],[1,2,1],[0,2,2]]},{"n":4,"roads":[[0,1,1],[0,2,1],[1,3,1],[2,3,1],[1,2,1]]},{"n":4,"roads":[[0,1,5],[1,2,5],[2,3,5],[0,3,20]]},{"n":5,"roads":[[0,1,2],[1,4,2],[0,2,2],[2,4,2],[0,3,1],[3,4,3]]},{"n":3,"roads":[[0,1,7],[1,2,8],[0,2,20]]},{"n":4,"roads":[[0,1,1],[1,2,1],[2,3,1],[0,3,3]]},{"n":5,"roads":[[0,1,1],[1,2,1],[2,4,1],[0,3,1],[3,4,2],[1,3,1]]},{"n":3,"roads":[[0,1,2],[1,2,2],[0,2,4]]}]},
{"slug":"11-maximum-probability-path","title":"Maximum Probability Path","method":"maxProbability","ret":"double","params":[("n","int"),("edges","int[][]"),("succProb","double[]"),("start","int"),("end","int")],"diff":"Medium","subtopic":"Dijkstra","desc":"An undirected graph has `n` vertices. Each edge `edges[i] = [u,v]` succeeds with probability `succProb[i]`. The probability of a path is the product of its edge probabilities. Return the maximum probability of reaching `end` from `start`, or 0 if no path exists. Input: `n`, `edges`, `succProb`, `start`, `end`. Output: the maximum probability.","cons":["1 <= n <= 10000","0 <= edges.length <= 20000","0 <= succProb[i] <= 1","0 <= start,end < n","No parallel edges"],"time":"O((n+m) log n)","space":"O(n+m)","py":"        graph=[[] for _ in range(n)]\n        for (u,v),p in zip(edges,succProb): graph[u].append((v,p)); graph[v].append((u,p))\n        best=[0.0]*n; best[start]=1.0; heap=[(-1.0,start)]\n        while heap:\n            neg,u=heappop(heap); prob=-neg\n            if prob < best[u]: continue\n            if u==end: return prob\n            for v,p in graph[u]:\n                cand=prob*p\n                if cand>best[v]: best[v]=cand; heappush(heap,(-cand,v))\n        return 0.0","java":"        List<double[]>[] graph=new ArrayList[n]; for(int i=0;i<n;i++) graph[i]=new ArrayList<>();\n        for(int i=0;i<edges.length;i++){int u=edges[i][0],v=edges[i][1]; graph[u].add(new double[]{v,succProb[i]}); graph[v].add(new double[]{u,succProb[i]});}\n        double[] best=new double[n]; best[start]=1.0; PriorityQueue<double[]> pq=new PriorityQueue<>((a,b)->Double.compare(b[0],a[0])); pq.offer(new double[]{1.0,start});\n        while(!pq.isEmpty()){double[] cur=pq.poll(); double p=cur[0]; int u=(int)cur[1]; if(p<best[u])continue; if(u==end)return p; for(double[] e:graph[u]){int v=(int)e[0]; double cand=p*e[1]; if(cand>best[v]){best[v]=cand;pq.offer(new double[]{cand,v});}}}\n        return 0.0;","examples":[({"n":3,"edges":[[0,1],[1,2],[0,2]],"succProb":[0.5,0.5,0.2],"start":0,"end":2},0.25),({"n":3,"edges":[[0,1]],"succProb":[0.5],"start":0,"end":2},0.0)],"tests":[{"n":1,"edges":[],"succProb":[],"start":0,"end":0},{"n":2,"edges":[[0,1]],"succProb":[1.0],"start":0,"end":1},{"n":2,"edges":[[0,1]],"succProb":[0.0],"start":0,"end":1},{"n":4,"edges":[[0,1],[1,3],[0,2],[2,3]],"succProb":[0.5,0.5,0.8,0.4],"start":0,"end":3},{"n":3,"edges":[[0,1],[1,2]],"succProb":[0.9,0.9],"start":0,"end":2},{"n":4,"edges":[[0,1],[1,2],[2,3],[0,3]],"succProb":[0.9,0.9,0.9,0.5],"start":0,"end":3},{"n":3,"edges":[[0,1],[0,2]],"succProb":[0.2,0.7],"start":0,"end":2},{"n":5,"edges":[[0,1],[1,4],[0,2],[2,3],[3,4]],"succProb":[0.8,0.8,0.9,0.9,0.9],"start":0,"end":4},{"n":4,"edges":[[0,1],[1,2]],"succProb":[0.7,0.6],"start":2,"end":0}]},
{"slug":"12-shortest-route-with-one-discount","title":"Shortest Route With One Discount","method":"minimumCostWithDiscount","ret":"long","params":[("n","int"),("edges","int[][]"),("source","int"),("destination","int")],"diff":"Medium","subtopic":"Dijkstra","desc":"An undirected connected graph has `n` vertices and positive weighted edges `[u,v,cost]`. Travel costs `cost`, except that you may choose at most one edge on your route and pay `floor(cost/2)` for it. Return the minimum possible cost from `source` to `destination`. Input: `n`, `edges`, `source`, `destination`. Output: the minimum cost.","cons":["2 <= n <= 10000","n-1 <= edges.length <= 50000","1 <= cost <= 1000000000","The graph is connected and has no parallel edges"],"time":"O((n+m) log n)","space":"O(n+m)","py":"        graph=[[] for _ in range(n)]\n        for u,v,w in edges: graph[u].append((v,w)); graph[v].append((u,w))\n        inf=10**30; dist=[[inf,inf] for _ in range(n)]; dist[source][0]=0; heap=[(0,source,0)]\n        while heap:\n            d,u,used=heappop(heap)\n            if d!=dist[u][used]: continue\n            if u==destination: return d\n            for v,w in graph[u]:\n                if d+w<dist[v][used]: dist[v][used]=d+w; heappush(heap,(d+w,v,used))\n                if not used and d+w//2<dist[v][1]: dist[v][1]=d+w//2; heappush(heap,(d+w//2,v,1))\n        return -1","java":"        List<long[]>[] g=new ArrayList[n]; for(int i=0;i<n;i++)g[i]=new ArrayList<>();\n        for(int[] e:edges){g[e[0]].add(new long[]{e[1],e[2]});g[e[1]].add(new long[]{e[0],e[2]});}\n        long[][] d=new long[n][2]; for(long[] row:d)Arrays.fill(row,Long.MAX_VALUE); d[source][0]=0; PriorityQueue<long[]> pq=new PriorityQueue<>(Comparator.comparingLong(a->a[0])); pq.offer(new long[]{0,source,0});\n        while(!pq.isEmpty()){long[] c=pq.poll();long cost=c[0];int u=(int)c[1],used=(int)c[2];if(cost!=d[u][used])continue;if(u==destination)return cost;for(long[] e:g[u]){int v=(int)e[0];long w=e[1];if(cost+w<d[v][used]){d[v][used]=cost+w;pq.offer(new long[]{cost+w,v,used});}if(used==0&&cost+w/2<d[v][1]){d[v][1]=cost+w/2;pq.offer(new long[]{cost+w/2,v,1});}}}\n        return -1;","examples":[({"n":3,"edges":[[0,1,6],[1,2,6],[0,2,20]],"source":0,"destination":2},9),({"n":2,"edges":[[0,1,7]],"source":0,"destination":1},3)],"tests":[{"n":2,"edges":[[0,1,1]],"source":0,"destination":1},{"n":3,"edges":[[0,1,10],[1,2,10]],"source":0,"destination":2},{"n":3,"edges":[[0,1,5],[1,2,5],[0,2,20]],"source":0,"destination":2},{"n":4,"edges":[[0,1,2],[1,3,10],[0,2,6],[2,3,6]],"source":0,"destination":3},{"n":4,"edges":[[0,1,100],[1,2,1],[2,3,1]],"source":0,"destination":3},{"n":3,"edges":[[0,1,3],[1,2,4]],"source":2,"destination":0},{"n":3,"edges":[[0,1,1000000000],[1,2,1000000000]],"source":0,"destination":2},{"n":4,"edges":[[0,1,3],[1,2,3],[2,3,3],[0,3,20]],"source":0,"destination":3},{"n":2,"edges":[[0,1,2]],"source":0,"destination":0}]},
{"slug":"13-bellman-ford-distance-list","title":"Bellman-Ford Distance List","method":"bellmanFord","ret":"long[]","params":[("n","int"),("edges","int[][]"),("source","int")],"diff":"Medium","subtopic":"Bellman-Ford","desc":"A directed weighted graph has vertices `0..n-1` and edges `[u,v,w]`; edge weights may be negative. There are no negative-weight cycles reachable from `source`. Return the shortest distance from `source` to every vertex, using -1 for unreachable vertices. Input: `n`, `edges`, `source`. Output: a distance array.","cons":["1 <= n <= 1000","0 <= edges.length <= 10000","-100000 <= w <= 100000","No negative cycle is reachable from source; all shortest distances fit in signed 32-bit range"],"time":"O(n*m)","space":"O(n)","py":"        inf=10**30; dist=[inf]*n; dist[source]=0\n        for _ in range(n-1):\n            changed=False\n            for u,v,w in edges:\n                if dist[u]!=inf and dist[u]+w<dist[v]: dist[v]=dist[u]+w; changed=True\n            if not changed: break\n        return [-1 if x==inf else x for x in dist]","java":"        long inf=Long.MAX_VALUE/4; long[] d=new long[n]; Arrays.fill(d,inf); d[source]=0;\n        for(int pass=0;pass<n-1;pass++){boolean changed=false;for(int[] e:edges)if(d[e[0]]!=inf&&d[e[0]]+e[2]<d[e[1]]){d[e[1]]=d[e[0]]+e[2];changed=true;}if(!changed)break;}\n        for(int i=0;i<n;i++)if(d[i]==inf)d[i]=-1; return d;","examples":[({"n":5,"edges":[[0,1,6],[0,2,7],[1,2,8],[1,3,5],[1,4,-4],[2,3,-3],[2,4,9],[3,1,-2],[4,0,2],[4,3,7]],"source":0},[0,2,7,4,-2]),({"n":3,"edges":[[0,1,4]],"source":0},[0,4,-1])],"tests":[{"n":1,"edges":[],"source":0},{"n":2,"edges":[[0,1,-5]],"source":0},{"n":3,"edges":[[0,1,2],[1,2,3]],"source":0},{"n":3,"edges":[[0,1,2],[1,2,-5],[0,2,1]],"source":0},{"n":4,"edges":[[0,1,1],[2,3,-2]],"source":0},{"n":4,"edges":[[0,1,5],[0,2,2],[2,1,1],[1,3,3]],"source":0},{"n":3,"edges":[[1,2,1],[2,1,1]],"source":0},{"n":4,"edges":[[0,1,-1],[1,2,2],[0,2,5]],"source":0},{"n":4,"edges":[[0,1,100],[1,2,-200],[2,3,50]],"source":0}]},
{"slug":"14-minimum-edge-reversals-from-source","title":"Minimum Edge Reversals From Source","method":"minimumReversalsFromSource","ret":"int[]","params":[("n","int"),("directedEdges","int[][]"),("source","int")],"diff":"Medium","subtopic":"Dijkstra","desc":"Each directed edge `[u,v]` can be traversed from `u` to `v` at cost 0, or from `v` to `u` after reversing it at cost 1. For every vertex, find the minimum number of edge reversals needed for a route from `source`; return -1 when no route exists even after reversals. Input: `n`, `directedEdges`, `source`. Output: one minimum cost per vertex.","cons":["1 <= n <= 10000","0 <= directedEdges.length <= 50000","0 <= u,v < n and u != v","There are no duplicate directed edges"],"time":"O((n+m) log n)","space":"O(n+m)","py":"        g=[[] for _ in range(n)]\n        for u,v in directedEdges: g[u].append((v,0)); g[v].append((u,1))\n        inf=10**9; dist=[inf]*n; dist[source]=0; heap=[(0,source)]\n        while heap:\n            d,u=heappop(heap)\n            if d!=dist[u]:continue\n            for v,w in g[u]:\n                if d+w<dist[v]:dist[v]=d+w;heappush(heap,(d+w,v))\n        return [-1 if x==inf else x for x in dist]","java":"        List<int[]>[] g=new ArrayList[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();\n        for(int[] e:directedEdges){g[e[0]].add(new int[]{e[1],0});g[e[1]].add(new int[]{e[0],1});}\n        int inf=1000000000;int[] d=new int[n];Arrays.fill(d,inf);d[source]=0;PriorityQueue<int[]> pq=new PriorityQueue<>(Comparator.comparingInt(a->a[0]));pq.offer(new int[]{0,source});\n        while(!pq.isEmpty()){int[] c=pq.poll();int cost=c[0],u=c[1];if(cost!=d[u])continue;for(int[] e:g[u])if(cost+e[1]<d[e[0]]){d[e[0]]=cost+e[1];pq.offer(new int[]{d[e[0]],e[0]});}}\n        for(int i=0;i<n;i++)if(d[i]==inf)d[i]=-1;return d;","examples":[({"n":4,"directedEdges":[[0,1],[2,1],[2,3]],"source":0},[0,0,1,1]),({"n":3,"directedEdges":[[1,2]],"source":0},[0,-1,-1])],"tests":[{"n":1,"directedEdges":[],"source":0},{"n":2,"directedEdges":[[0,1]],"source":1},{"n":3,"directedEdges":[[0,1],[1,2]],"source":2},{"n":4,"directedEdges":[[0,1],[2,3]],"source":0},{"n":4,"directedEdges":[[1,0],[2,1],[2,3]],"source":0},{"n":5,"directedEdges":[[0,1],[1,2],[3,4]],"source":0},{"n":4,"directedEdges":[[0,1],[0,2],[3,2]],"source":3},{"n":3,"directedEdges":[[0,1],[2,1]],"source":1},{"n":5,"directedEdges":[[0,1],[2,1],[2,3],[4,3]],"source":0}]}
]

roster_path=ROOT/"problems"/"roster.json"; roster=json.loads(roster_path.read_text())
for p in tasks:
    folder=BASE/p["slug"]; folder.mkdir()
    params=[{"name":name,"type":typ} for name,typ in p["params"]]
    meta={"title":p["title"],"difficulty":p["diff"],"subtopic":p["subtopic"],"companies":["Google","Amazon","Microsoft"],"description":p["desc"],"constraints":p["cons"],"hints":["Represent each edge as a transition whose cost matches the route rule.","Keep the best distance for each required state and ignore stale priority-queue entries."],"examples":[{"input":", ".join(f"{k} = {json.dumps(v)}" for k,v in x.items()),"output":json.dumps(y,separators=(",",":")) if isinstance(y,list) else str(y)} for x,y in p["examples"]],"timeComplexity":p["time"],"spaceComplexity":p["space"],"compare":"float" if p["ret"]=="double" else "exact","signature":{"kind":"function","method":p["method"],"params":params,"returns":p["ret"]}}
    (folder/"problem.json").write_text(json.dumps(meta,indent=2)+"\n")
    pytypes={"int":"int","int[][]":"List[List[int]]","double[]":"List[float]"}
    pyparams="".join(f", {name}: {pytypes[typ]}" for name,typ in p["params"])
    pyret="List[int]" if p["ret"] in ("int[]","long[]") else "float" if p["ret"]=="double" else "int"
    (folder/"solution.py").write_text(f"class Solution:\n    def {p['method']}(self{pyparams}) -> {pyret}:\n"+p["py"]+"\n")
    jparams=", ".join(f"{typ} {name}" for name,typ in p["params"])
    jret={"int":"int","long":"long","double":"double","int[]":"int[]","long[]":"long[]"}[p["ret"]]
    (folder/"Solution.java").write_text(f"class Solution {{\n    public {jret} {p['method']}({jparams}) {{\n"+p["java"]+"\n    }\n}\n")
    cases=[x for x,_ in p["examples"]]+p["tests"]
    (folder/"tests.py").write_text("def visible():\n    return "+repr([{"in":x} for x in cases[:3]])+"\n\ndef hidden():\n    return "+repr([{"in":x} for x in cases[3:]])+"\n")
    roster.setdefault("shortest-paths",[]).append([p["slug"],p["title"],p["diff"],p["subtopic"],None])
roster_path.write_text(json.dumps(roster,indent=2)+"\n")
print(f"Created {len(tasks)} shortest-path questions")
